import type { VariableConfig } from '../../Variable'

/**
 * Configuration type for masked variables
 */
export type MaskedVariableType<Type extends string = string> = VariableConfig<Type> & {
    /** Whether to use confirmation for the masked field */
    useConfirmation?: boolean
    /** Whether to use encryption for the masked field */
    useEncryption?: boolean
}

/**
 * A Variable for a masked field.
 *
 * @see https://docs.servicenow.com/csh?topicname=variable-types.html&version=latest
 *
 * @param config - Configuration for the masked variable including:
 *   * **question** - Question text displayed to the user
 *   * **useConfirmation**? - Whether to use confirmation for the masked field
 *   * **useEncryption**? - Whether to use encryption for the masked field
 *   * **defaultValue**? - Default value for the variable
 *   * And all other properties from the base Variable type
 */
export function MaskedVariable(config: MaskedVariableType) {
    return config
}
